import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUIDv7 primary key generated by Postgres 18 (time-ordered, so inserts stay index-friendly). */
export const id = () => uuid("id").default(sql`uuidv7()`).primaryKey();

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

export const createdAt = () => timestamptz("created_at").defaultNow().notNull();

export const updatedAt = () =>
  timestamptz("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull();
